package org.apache.commons.lang3.text.translate;

import org.junit.Test;
import static org.junit.Assert.*;
import static org.evosuite.runtime.EvoAssertions.*;
import java.nio.CharBuffer;
import org.evosuite.runtime.EvoRunner;
import org.evosuite.runtime.EvoRunnerParameters;
import org.junit.runner.RunWith;

@RunWith(EvoRunner.class)
@EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, separateClassLoader = false)
public class NumericEntityUnescaper_ESTest_test1 extends NumericEntityUnescaper_ESTest_scaffolding {

    /**
     * A hex numeric entity ("&#X;") that has no digits between the "X" marker
     * and the ";" is malformed. The unescaper cannot parse an entity value, so
     * it leaves the input completely untranslated and returns it verbatim.
     */
    @Test(timeout = 4000)
    public void translateMalformedHexEntityLeavesInputUnchanged() throws Throwable {
        // Input: "&#X;" followed by three trailing NUL ('�') characters.
        // "&#X" looks like the start of a hex entity, but no hex digits follow.
        char[] inputChars = new char[7];
        inputChars[0] = '&';
        inputChars[1] = '#';
        inputChars[2] = 'X';
        inputChars[3] = ';';
        // inputChars[4..6] keep the default char value: '�'.
        CharBuffer input = CharBuffer.wrap(inputChars);

        // No OPTION values supplied, so default unescaper behaviour applies.
        NumericEntityUnescaper.OPTION[] noOptions = new NumericEntityUnescaper.OPTION[0];
        NumericEntityUnescaper unescaper = new NumericEntityUnescaper(noOptions);

        String result = unescaper.translate((CharSequence) input);

        // Nothing is translated; the original characters are returned unchanged.
        assertEquals("&#X;���", result);
    }
}
